/**
 * Diagnostic vocabulary shared by the circuit validator, the PCB checker, the UI
 * and the AI tutor's evidence payload.
 *
 * Every diagnostic the student sees is produced by a deterministic check over the
 * circuit graph. Nothing here is generated by a language model.
 */

export type Severity = 'error' | 'warning' | 'info' | 'pass';

export type DiagnosticCode =
  /* circuit */
  | 'NO_SUPPLY'
  | 'SUPPLY_UNCONNECTED'
  | 'NO_LED'
  | 'LED_NOT_SEATED'
  | 'OPEN_CIRCUIT'
  | 'FLOATING_PIN'
  | 'LED_REVERSED'
  | 'MISSING_RESISTOR'
  | 'SUPPLY_SHORT'
  | 'COMPONENT_SHORTED'
  | 'OVERCURRENT'
  | 'ABOVE_RATED_CURRENT'
  | 'SUPPLY_BELOW_VF'
  | 'LED_TOO_DIM'
  | 'CAPACITOR_REVERSED'
  | 'CAPACITOR_BLOCKS_DC'
  | 'MODEL_LIMIT'
  | 'SWITCH_OPEN'
  | 'FUSE_BLOWN'
  | 'FUSE_OVER_RATING'
  | 'DIODE_REVERSED'
  | 'BUZZER_REVERSED'
  | 'POT_WIPER_UNUSED'
  | 'INDUCTOR_DC_SHORT'
  | 'CIRCUIT_VALID'
  /* pcb */
  | 'PCB_NO_FOOTPRINTS'
  | 'PCB_MISSING_TRACE'
  | 'PCB_NET_UNCONNECTED'
  | 'PCB_WRONG_CONNECTION'
  | 'PCB_CLEARANCE'
  | 'PCB_FOOTPRINT_OVERLAP'
  | 'PCB_TRACE_OFF_BOARD'
  | 'PCB_VALID';

/** Where a diagnostic points, so the UI can highlight the right object. */
export interface DiagnosticTarget {
  componentIds?: string[];
  pinIds?: string[];
  wireIds?: string[];
  netNames?: string[];
  holeIds?: string[];
  padIds?: string[];
  traceIds?: string[];
}

export interface Diagnostic {
  code: DiagnosticCode;
  severity: Severity;
  /** One-line summary shown in the issues list. */
  title: string;
  /** Plain-language detail, stating the measured evidence. */
  detail: string;
  /**
   * The concrete numbers this diagnostic was derived from. The AI tutor is
   * instructed to quote only from here, never to invent measurements.
   */
  evidence?: Record<string, string | number | boolean>;
  target?: DiagnosticTarget;
}

export const SEVERITY_RANK: Record<Severity, number> = {
  error: 0,
  warning: 1,
  info: 2,
  pass: 3,
};

export function sortDiagnostics(list: Diagnostic[]): Diagnostic[] {
  return [...list].sort((a, b) => SEVERITY_RANK[a.severity] - SEVERITY_RANK[b.severity]);
}

export function countBySeverity(list: Diagnostic[]): Record<Severity, number> {
  const out: Record<Severity, number> = { error: 0, warning: 0, info: 0, pass: 0 };
  for (const d of list) out[d.severity] += 1;
  return out;
}

export function hasErrors(list: Diagnostic[]): boolean {
  return list.some((d) => d.severity === 'error');
}
